package com.queueguard.qms.service;
import com.queueguard.common.exception.*; import com.queueguard.qms.domain.*; import com.queueguard.qms.dto.QmsDtos.*; import com.queueguard.qms.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TenantService {
 private final OrganizationRepository organizations; private final MembershipRepository memberships;
 public TenantService(OrganizationRepository o,MembershipRepository m){organizations=o;memberships=m;}
 @Transactional public OrganizationView onboard(Long actor,CreateOrganizationRequest r){String name=r.name().trim();if(organizations.existsByNameIgnoreCase(name))throw new BusinessException(409,"ORGANIZATION_EXISTS","Organization name already exists");Organization o=new Organization();o.setName(name);o.setOrganizationType(r.organizationType().trim());o=organizations.save(o);Membership m=new Membership();m.setOrganization(o);m.setAuthUserId(actor);m.setRoles(Set.of(OrganizationRole.ORG_ADMIN));memberships.save(m);return ov(o);}
 @Transactional(readOnly=true) public OrganizationView organization(Long actor,Long org){active(actor,org);return ov(org(org));}
 @Transactional(readOnly=true) public List<MembershipView> mine(Long actor){return memberships.findByAuthUserIdOrderByCreatedAtDesc(actor).stream().filter(m->m.getStatus()==MembershipStatus.ACTIVE).map(this::mv).toList();}
 @Transactional(readOnly=true) public List<MembershipView> list(Long actor,Long org){admin(actor,org);return memberships.findByOrganizationIdOrderByCreatedAtAsc(org).stream().map(this::mv).toList();}
 @Transactional(readOnly=true) public MembershipView membership(Long actor,Long org,Long id){admin(actor,org);return mv(member(id,org));}
 @Transactional public MembershipView add(Long actor,Long org,AddMembershipRequest r){admin(actor,org);if(r.userId().equals(actor))throw new ForbiddenException("Administrators cannot alter their own membership");if(memberships.findByOrganizationIdAndAuthUserId(org,r.userId()).isPresent())throw new BusinessException(409,"MEMBERSHIP_EXISTS","User already belongs to this organization");Membership m=new Membership();m.setOrganization(org(org));m.setAuthUserId(r.userId());m.setRoles(r.roles());return mv(memberships.save(m));}
 @Transactional public MembershipView roles(Long actor,Long org,Long id,UpdateRolesRequest r){admin(actor,org);Membership m=member(id,org);if(m.getAuthUserId().equals(actor))throw new ForbiddenException("Administrators cannot alter their own roles");m.setRoles(r.roles());return mv(m);}
 @Transactional public MembershipView status(Long actor,Long org,Long id,UpdateMembershipStatusRequest r){admin(actor,org);Membership m=member(id,org);if(m.getAuthUserId().equals(actor))throw new ForbiddenException("Administrators cannot alter their own membership");m.setStatus(r.status());return mv(m);}
 public Membership active(Long user,Long org){Membership m=memberships.findByOrganizationIdAndAuthUserId(org,user).orElseThrow(()->new NotFoundException("Organization not found"));if(m.getStatus()!=MembershipStatus.ACTIVE||m.getOrganization().getStatus()!=OrganizationStatus.ACTIVE)throw new ForbiddenException("Active organization membership required");return m;}
 private void admin(Long user,Long org){if(!active(user,org).getRoles().contains(OrganizationRole.ORG_ADMIN))throw new ForbiddenException("Organization administrator permission required");}
 private Organization org(Long id){return organizations.findById(id).orElseThrow(()->new NotFoundException("Organization not found"));}
 private Membership member(Long id,Long org){return memberships.findById(id).filter(m->m.getOrganization().getId().equals(org)).orElseThrow(()->new NotFoundException("Membership not found"));}
 private OrganizationView ov(Organization o){return new OrganizationView(o.getId(),o.getName(),o.getOrganizationType(),o.getStatus(),o.getCreatedAt().toString(),o.getUpdatedAt().toString());}
 private MembershipView mv(Membership m){return new MembershipView(m.getId(),m.getOrganization().getId(),m.getAuthUserId(),m.getStatus(),Set.copyOf(m.getRoles()),m.getCreatedAt().toString());}
}
